"""A sample tool made only from the existing pieces, to prove one file adds a tool."""

from pathlib import Path, PurePosixPath

from plan_review.harness.agent_files import TomlAgents
from plan_review.harness.distribution import MarketplacePlugin
from plan_review.harness.harness import Harness
from plan_review.harness.waiting import PollingWaiting
from plan_review.harness.wording import Wording
from plan_review.settings.agent_rules import AgentRules

HARNESS = Harness(
    key="sample-tool",
    name="Sample Tool",
    wording=Wording(
        arguments="<args>",
        agent_prefix="sample-",
        agent_override=".sample/agents/<name>.toml",
        rules_file="SAMPLE.md",
        rules_also="",
        harness_folder=".sample/",
        start_agent="by calling the sample tool.",
        start_together="call it once per agent",
        unknown_agent="stop.",
    ),
    agent_files=TomlAgents(
        folder=PurePosixPath("sample_files"), mark="generated by sample", extra_files={}
    ),
    distribution=MarketplacePlugin(
        tool_name="Sample Tool",
        program="sampletool",
        marketplace="sample-market",
        plugin="plan-review",
        marker=".sample-plugin/plugin.json",
        after_upgrade="Sample is updated.",
    ),
    waiting=PollingWaiting(),
    rules=AgentRules(
        own_prefix="sample-",
        defaults={},
        models=None,
        efforts=None,
        project_agent_folders=(PurePosixPath(".sample/agents"),),
        user_agent_folders=lambda: (),
        agent_suffix=".toml",
        own_agent_file=lambda role: Path(f"sample-{role}.toml"),
    ),
)
